module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out,
    output out_n
);

    // Declare intermediate wires for AND gate outputs
    wire and_ab;
    wire and_cd;

    // Perform first layer AND operations using continuous assignments
    assign and_ab = a & b;
    assign and_cd = c & d;

    // Second layer OR operation
    assign out = and_ab | and_cd;

    // Inverted output generated by negating out
    assign out_n = ~out;

endmodule